WITH recent_subscriptions AS (SELECT *, DATE_FORMAT(start_date, 'MMM yyyy') AS start_date_label FROM subscriptions WHERE monthly_fee < 70), Agg AS (SELECT plan, MIN(monthly_fee) AS min_monthly_fee, SUM(CASE WHEN status = 'PAUSED' THEN monthly_fee ELSE 0 END) AS paused_monthly_fee FROM recent_subscriptions GROUP BY plan) SELECT * FROM Agg WHERE paused_monthly_fee < 21 ORDER BY paused_monthly_fee, min_monthly_fee DESC
